INSERT INTO `news_articles` (`slug`, `title`, `category`, `date`, `excerpt`, `body`, `image`, `image_fit`, `source_url`, `related_href`, `related_label`) VALUES ('mundus-vini-gold-medals', '{"en":"Gold medals for Badagoni at Mundus Vini","ka":""}', '{"en":"Awards","ka":""}', '2025-11-28', '{"en":"Four wines receive gold medals at the international wine competition in Germany.","ka":""}', '{"en":"Four Badagoni wines earned gold medals at Mundus Vini in Germany: Saperavi Reserve, Kakhetian Noble dry red, Alaverdi Tradition dry red, and Maestro Extra Brut sparkling wine.\n\nThe result brings recognition to both still and sparkling wines in the collection. Among them is Maestro Extra Brut, which received its gold medal within months of its release.\n\nTogether, these wines offer different expressions of Badagoni, from its red wines to a more recent addition to the sparkling collection.","ka":""}', '/images/newsroom/mundus-vini.jpg', 'contain', 'https://badagoni.com/mundus-vini-germany-badagoni-wines-won-gold-medals-once-again/', '/catalogue', '{"en":"Explore the wines","ka":""}');
INSERT INTO `news_articles` (`slug`, `title`, `category`, `date`, `excerpt`, `body`, `image`, `image_fit`, `source_url`, `related_href`, `related_label`) VALUES ('saperavi-reserve-best-of-show', '{"en":"Saperavi Reserve named Best of Show Georgia Red","ka":""}', '{"en":"Awards","ka":""}', '2025-11-28', '{"en":"Saperavi Reserve 2010 receives a Best of Show Georgia Red distinction at Mundus Vini’s Summer Tasting.","ka":""}', '{"en":"Badagoni Saperavi Reserve was awarded Best of Show Georgia Red at Mundus Vini Summer Tasting in Germany. The distinction recognises a limited wine made from the 2010 harvest.\n\nThe wine comes from Saperavi grown in Badagoni’s vineyards near Alaverdi Monastery. Its connection to this part of Kakheti is central to the story behind the bottle.\n\nFor Badagoni, the result brings further international recognition to Georgian wine and to the character of Saperavi.","ka":""}', '/images/newsroom/saperavi-reserve.jpg', 'contain', 'https://badagoni.com/badagoni-saperavi-reserve-becomes-an-owner-of-the-highest-award-best-of-show-georgia-red/', '/wines/saperavi-reserve', '{"en":"About Saperavi Reserve","ka":""}');
INSERT INTO `news_articles` (`slug`, `title`, `category`, `date`, `excerpt`, `body`, `image`, `image_fit`, `source_url`, `related_href`, `related_label`) VALUES ('sanlian-lifeweek-georgian-wine', '{"en":"A Georgian wine story in Sanlian Lifeweek","ka":""}', '{"en":"In the press","ka":""}', '2025-11-28', '{"en":"The Chinese magazine explores Georgia’s winemaking heritage, qvevri tradition, and local cuisine.","ka":""}', '{"en":"Badagoni featured in Sanlian Lifeweek, a Chinese magazine, as part of a story on travel and gastronomy in Georgia.\n\nThe feature visits Alaverdi Monastery’s historic cellar and explores traditional qvevri winemaking. It traces the connection between this living tradition and the wines made by the monks.\n\nNearby, Badagoni Home offers another part of that story through Georgian and Tushetian cuisine. The coverage highlights dishes including kotori and khavitsi, placing food alongside wine in its portrait of the region.","ka":""}', '/images/newsroom/sanlian-lifeweek.jpg', 'contain', 'https://badagoni.com/badagoni-featured-in-the-influential-chinese-magazine-sanlian-lifeweek/', '/alaverdi-monastery-cellar', '{"en":"Discover Alaverdi’s cellar","ka":""}');
